#include "safety_obstacle.h"
#include "config.h"

ObstacleDetector::ObstacleDetector(UltrasonicSensor& frontUS, UltrasonicSensor& sideUS,
                                   VibrationMotor& vib, VoicePlayer& voice, BuzzerActuator& buzzer)
    : _frontUS(frontUS), _sideUS(sideUS), _vib(vib), _voice(voice), _buzzer(buzzer),
      _safeDist(DIST_SAFE_CM), _warnDist(DIST_WARN_CM), _dangerDist(DIST_DANGER_CM),
      _lastVoiceTime(0) {}

ObstacleResult ObstacleDetector::update() {
    ObstacleResult result;
    result.level = OBS_SAFE;
    result.frontDist = _frontUS.getDistanceCm();
    result.sideDist = _sideUS.getDistanceCm();

    bool frontClose = result.frontDist < _safeDist;
    bool sideClose = result.sideDist < _safeDist;

    if (sideClose && !frontClose) {
        result.vibDir = VIB_LEFT;
    } else if (frontClose && !sideClose) {
        result.vibDir = VIB_CENTER;
    } else if (frontClose && sideClose) {
        result.vibDir = (result.sideDist < result.frontDist) ? VIB_LEFT : VIB_CENTER;
    } else {
        result.vibDir = VIB_CENTER;
    }

    float minDist = fminf(result.frontDist, result.sideDist);

    if (minDist <= _dangerDist) {
        result.level = OBS_DANGER;
        _vib.obstacleFeedback(minDist, result.vibDir);
        _buzzer.fastBeep();
        if (millis() - _lastVoiceTime > VOICE_COOLDOWN_MS) {
            _voice.play(VOICE_OBSTACLE_AHEAD);
            _lastVoiceTime = millis();
        }
    } else if (minDist <= _warnDist) {
        result.level = OBS_WARNING;
        _vib.obstacleFeedback(minDist, result.vibDir);
        _buzzer.off();
    } else if (minDist <= _safeDist) {
        result.level = OBS_SAFE;
        _vib.obstacleFeedback(minDist, result.vibDir);
        _buzzer.off();
    } else {
        result.level = OBS_SAFE;
        _vib.stopAll();
        _buzzer.off();
    }

    return result;
}

void ObstacleDetector::setSafeDistance(float cm) { _safeDist = cm; }
void ObstacleDetector::setWarnDistance(float cm) { _warnDist = cm; }
void ObstacleDetector::setDangerDistance(float cm) { _dangerDist = cm; }




